 G=Path(__file__).resolve().parent.parent;D=R/'stage307';assert not D.exists();D.mkdir(mode=0o700);start,cpu=time.perf_counter(),time.process_time();S=R/'stage306';p=read(S/'plan.json');cfg=read(S/'candidate-config.json');ns={}
